#!/bin/bash
# Ledger helpers. LEDGER rows: date<TAB>sku<TAB>qty<TAB>kind<TAB>ref (kind IN or OUT).
LEDGER=${LEDGER:-data/ledger.tsv}
# qty_ok QTY: succeeds when QTY is a whole number.
qty_ok() { [[ $1 =~ ^[0-9]+$ ]]; }
# onhand SKU: units in stock = IN total minus OUT total.
onhand() { awk -F'\t' -v s="$1" '!/^#/ && NF && $2 == s { if ($4 == "IN") t += $3; else t -= $3 } END { print t }' "$LEDGER"; }

---
src/move.sh:2:# move.sh SKU QTY KIND REF: record a stock movement (KIND = IN or OUT). An OUT may not exceed the on-hand quantity.
src/move.sh:7:qty_ok "$qty" || { echo "quantity must be a whole number: $qty" >&2; exit 2; }
src/move.sh:10:  have=$(onhand "$sku")
src/report.sh:8:  echo "$sku $name $(onhand "$sku")"
spec/stock.spec.sh:4:qty_ok 12 || { echo "qty_ok 12"; fail=1; }
spec/stock.spec.sh:5:! qty_ok 1.5 || { echo "qty_ok 1.5 accepted"; fail=1; }
spec/stock.spec.sh:6:! qty_ok abc || { echo "qty_ok abc accepted"; fail=1; }
spec/stock.spec.sh:8:[ "$(LEDGER=$t onhand A-100)" = 18 ] || { echo "onhand A-100"; fail=1; }
spec/stock.spec.sh:9:[ "$(LEDGER=$t onhand B-010)" = 5 ] || { echo "onhand B-010"; fail=1; }
docs/design/ledger-rules.md:3:対応する実装: src/lib/stock.sh, src/move.sh
---
spec:
report.spec.sh
stock.spec.sh

tools:
check
close-month

